import React, { useEffect, useRef, useState } from 'react';
import './Home.css';
import { Link } from 'react-router-dom';

const PANELS = [
  { id: 'banner' },
  { id: 'concept' },
  { id: 'hands-on' },
  { id: 'multidisciplinary' },
  { id: 'faculty' },
  { id: 'cta' }
];

const Home = () => {
  const deckRef = useRef(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  
  useEffect(() => {
    if (isPaused) return;
    const timer = setInterval(() => {
      setActiveIndex(current => {
        const next = current >= PANELS.length - 1 ? 0 : current + 1;
        const deck = deckRef.current;
        if (deck) {
          const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
          deck.scrollTo({
            left: next * deck.clientWidth,
            behavior: mediaQuery.matches ? 'auto' : 'smooth'
          });
        }
        return next; // we let scroll sync it too, but just in case
      });
    }, 8000);
    return () => clearInterval(timer);
  }, [isPaused]);

  useEffect(() => {
    const deck = deckRef.current;
    if (!deck) return;

    const sync = () => {
      const i = Math.round(deck.scrollLeft / deck.clientWidth);
      if (i !== activeIndex) {
        setActiveIndex(i);
        const panelId = PANELS[i]?.id;
        if (panelId && window.location.hash !== `#${panelId}`) {
          window.history.replaceState(null, null, `#${panelId}`);
        }
      }
    };

    deck.addEventListener('scroll', sync, { passive: true });
    window.addEventListener('resize', sync, { passive: true });

    const handleWheel = (e) => {
      if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) {
        const atStart = deck.scrollLeft === 0 && e.deltaY < 0;
        const atEnd = deck.scrollLeft + deck.clientWidth >= deck.scrollWidth && e.deltaY > 0;
        if (!atStart && !atEnd) {
          e.preventDefault();
          deck.scrollLeft += e.deltaY;
        }
      }
    };
    deck.addEventListener('wheel', handleWheel, { passive: false });

    const handleKeyDown = (e) => {
      let j = activeIndex;
      if (e.key === 'ArrowRight' || e.key === 'PageDown') j = Math.min(PANELS.length - 1, activeIndex + 1);
      else if (e.key === 'ArrowLeft' || e.key === 'PageUp') j = Math.max(0, activeIndex - 1);
      else if (e.key === 'Home') j = 0;
      else if (e.key === 'End') j = PANELS.length - 1;
      
      if (j !== activeIndex) {
        scrollToIndex(j);
      }
    };
    document.addEventListener('keydown', handleKeyDown);

    const hash = window.location.hash.slice(1);
    const initialIndex = PANELS.findIndex(p => p.id === hash);
    if (initialIndex > 0) {
      setTimeout(() => {
        deck.scrollTo({
          left: initialIndex * deck.clientWidth,
          behavior: 'auto'
        });
      }, 100);
    }

    return () => {
      deck.removeEventListener('scroll', sync);
      window.removeEventListener('resize', sync);
      deck.removeEventListener('wheel', handleWheel);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [activeIndex]);

  const scrollToIndex = (index) => {
    const deck = deckRef.current;
    if (!deck) return;
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    deck.scrollTo({
      left: index * deck.clientWidth,
      behavior: mediaQuery.matches ? 'auto' : 'smooth'
    });
  };

  const handleRegisterClick = (e) => {
    e.preventDefault();
    alert('Registration opens soon');
  };

  return (
    <div className="deck-wrapper"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      onTouchStart={() => setIsPaused(true)}
      onTouchEnd={() => setIsPaused(false)}
    >


<div className="top-nav">
        <Link to="/program" className="prog-pill">Scientific program</Link>
        <a className="reg-pill" href="#" onClick={handleRegisterClick}>Register</a>
      </div>

<div className="deck" id="deck" ref={deckRef}>

  
  <section className="panel p-banner" aria-label="Welcome">
    <h1 className="sr-only">Thyroid Intervention Summit 2026 — 27–28 November 2026, Delhi-NCR</h1>
    <div className="pinner" style={{maxWidth:"900px", display:"flex", flexDirection:"column", alignItems:"center"}}>
      <img className="banner-img" src="data:image/png;base64," alt="Thyroid Intervention Summit 2026 · IR CME · 27–28 Nov 2026 · Delhi-NCR · Medanta – The Medicity, Gurgaon and Holiday Inn Aerocity, New Delhi · ISTS 2026 Pre-Conference · IR-Tutorials" />
      <a className="btn mt" href="#" onClick={handleRegisterClick}>Register now</a>
      <div className="eb">Early bird registration closes 15 Oct 2026</div>
      <div className="hint">Swipe to explore <span className="arw">→</span></div>
    </div>
  </section>

  
  <section className="panel" aria-label="The concept">
    <div className="pinner">
      <p className="eyebrow">The Concept</p>
      <h2 className="ptitle">Thyroid intervention, <em>from every angle</em></h2>
      <p className="ptext">A two-day CME built around the one discipline that decides everything — choosing the right patient. From imaging and cytology to ablation technique, and the surgical and endocrine perspectives that frame who should be treated, the summit brings the whole thyroid-nodule pathway into one room.</p>
      <div className="who"><b>Who it's for</b>Interventional radiologists &amp; radiologists · endocrine and head-&amp;-neck surgeons · nuclear medicine physicians · endocrinologists · cytopathologists · and DrNB-level trainees.</div>
    </div>
  </section>

  
  <section className="panel" aria-label="Hands-on workshop">
    <div className="pinner">
      <p className="eyebrow">Hands-On</p>
      <h2 className="ptitle">Put your hands <em>on the probe</em></h2>
      <p className="ptext">Day 1 runs faculty-supervised, phantom-based stations in radiofrequency and microwave ablation — small groups, parallel rotation, real technique under real guidance. Fifty seats, reserved for interventional radiology and radiology delegates.</p>
      <div className="chips">
        <span className="chip">RFA stations</span>
        <span className="chip">MWA stations</span>
        <span className="chip">Phantom-based</span>
        <span className="chip">50 seats</span>
      </div>
    </div>
  </section>

  
  <section className="panel" aria-label="Multidisciplinary">
    <div className="pinner">
      <p className="eyebrow">Under One Roof</p>
      <h2 className="ptitle">Surgeons, IRs, cytopathologists — <em>same table</em></h2>
      <p className="ptext">Thyroid ablation is never a single-specialty decision. The summit deliberately seats interventional radiology, endocrine and head-&amp;-neck surgery, nuclear medicine, endocrinology and cytopathology on the same faculty and the same panel — to argue out who should be treated, and how.</p>
      <div className="chips">
        <span className="chip">Interventional Radiology</span>
        <span className="chip">Endocrine &amp; H&amp;N Surgery</span>
        <span className="chip">Nuclear Medicine</span>
        <span className="chip">Endocrinology</span>
        <span className="chip">Cytopathology</span>
      </div>
    </div>
  </section>

  
  <section className="panel" aria-label="The faculty">
    <div className="pinner">
      <p className="eyebrow">The Faculty</p>
      <h2 className="ptitle">Access you won't <em>easily get elsewhere</em></h2>
      <p className="ptext">23 faculty across five specialties, national and international — including Prof. Marcin Barczyński of Jagiellonian University, Kraków. Two days in the room with the people defining the field, with patient selection as the throughline of every session.</p>
      <div className="chips">
        <span className="chip">23 Faculty</span>
        <span className="chip">5 Specialties</span>
        <span className="chip">International Faculty</span>
        <span className="chip">CME Accredited</span>
      </div>
    </div>
  </section>

  
  <section className="panel p-cta" aria-label="Register">
    <div className="pinner">
      <img className="cta-logo" src="data:image/png;base64," alt="TIS 2026" />
      <div className="cta-title">Join us in November</div>
      <div className="cta-meta">27–28 Nov 2026 · Delhi-NCR</div>
      <div className="cta-venue">Day 1 · Medanta – The Medicity, Gurgaon — hands-on workshop (ISTS 2026)<br/>Day 2 · Holiday Inn, Aerocity, New Delhi — scientific programme (IR-Tutorials)</div>
      <a className="btn mt" href="#" onClick={handleRegisterClick}>Register now</a>
      <div className="eb">Early bird registration closes 15 Oct 2026</div>
      <div className="cta-contact">Full programme &amp; faculty at program.html · Enquiries: registrations@irflo.net</div>
    </div>
  </section>

</div>

<button className="nav prev" id="prev" aria-label="Previous" onClick={() => scrollToIndex(activeIndex - 1)} disabled={activeIndex <= 0}>&#8249;</button>
<button className="nav next" id="next" aria-label="Next" onClick={() => scrollToIndex(activeIndex + 1)} disabled={activeIndex >= 5}>&#8250;</button>
<div className="dots" id="dots" role="tablist" aria-label="Sections">
        {[0, 1, 2, 3, 4, 5].map((i) => (
          <button
            key={i}
            className={`dot${i === activeIndex ? ' active' : ''}`}
            onClick={() => scrollToIndex(i)}
            aria-label={`Go to section ${i + 1}`}
          />
        ))}
      </div>


    </div>
  );
};

export default Home;
